import React from 'react'
import styled from 'styled-components'
import { FiCpu, FiMenu } from 'react-icons/fi'
import { IconButton } from '../../../styles/global'
import { TbPrompt } from 'react-icons/tb'
import { useChatAi } from '../context/ChatAiContext'

interface ChatSideBarProps {
  minimized?: boolean
  setMinimized: (minimized: boolean) => void
}
export const ChatSideBar: React.FC<ChatSideBarProps> = ({ minimized, setMinimized }) => {
  const [menuExpanded, setMenuExpanded] = React.useState(false)
  const { setSystemPrompt } = useChatAi()

  return (
    <Container expanded={menuExpanded}>
      <IconButton
        expanded={menuExpanded}
        title="Menu"
        onClick={() => setMenuExpanded(!menuExpanded)}
      >
        <FiMenu />
        {menuExpanded && <span>Settings</span>}
      </IconButton>
      {minimized && (
        <IconButton
          expanded={menuExpanded}
          title="Expand Chat"
          onClick={() => setMinimized(!minimized)}
        >
          <FiCpu />
          {menuExpanded && <span>Expand Chat</span>}
        </IconButton>
      )}
      <IconButton expanded={menuExpanded} title="Prompts">
        <TbPrompt />
        {menuExpanded && <IconButtonLabel>Prompts</IconButtonLabel>}
      </IconButton>
    </Container>
  )
}

interface ContainerProps {
  expanded: boolean
}

const Container = styled.div<ContainerProps>`
  width: ${(props) => (props.expanded ? '180px' : '40px')};
  position: static;
  right: 0;
  top: 40px;
  height: 100%;
  border-left: 1px solid #d0d0d0;
  padding: 4px;
  overflow-y: none;
  overflow-x: visible;
  background: #f8f8f8;
  margin-left: 6px;
  transition: width 0.3s ease-in-out;
`

const IconButtonLabel = styled.span`
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
`
